function findNote(root: Folder, title: string) {
  const stack = [root];
  while (stack.length > 0) {
    const folder = stack.pop()!;
    const hit = folder.notes.find((n) => n.title === title);
    if (hit) return hit;
    stack.push(...folder.children);
  }
  return null;
}

const links = new Map<string, string[]>([
  ["pitch", ["brief"]],
  ["brief", ["call"]],
  ["call", ["budget", "ideas"]],
  ["budget", ["pitch"]], // a loop back
]);

function related(start: string, maxHops = 2) {
  const dist = new Map([[start, 0]]); // also the visited set
  const queue = [start];
  let head = 0;
  while (head < queue.length) {
    const id = queue[head++];
    const d = dist.get(id)!;
    if (d === maxHops) continue;
    for (const next of links.get(id) ?? []) {
      if (dist.has(next)) continue; // seen: skip
      dist.set(next, d + 1);
      queue.push(next);
    }
  }
  dist.delete(start);
  return [...dist.keys()];
}
